-- Thai Language official M1-M3 indicators, OBEC Basic Education Core Curriculum B.E. 2551 (2008).
-- Source: official Thai OBEC curriculum PDF, Thai Language section, printed pages 45-55.
-- Idempotent data migration. Does not modify other subjects or curricula.
begin;
do $$
begin
 if not exists (select 1 from public.learning_curricula c join public.learning_curriculum_subjects cs on cs.curriculum_id=c.id join public.learning_subjects s on s.id=cs.subject_id where c.code='TH-BASIC-CORE-2008-2017' and s.code='THAI-LANGUAGE') then
  raise exception 'Thai national curriculum / Thai Language subject registration is required.';
 end if;
end $$;
insert into public.learning_skills(subject_id,code,name,description,status)
select id,'THAI-LANGUAGE','Thai Language','Official Thai Language standards: reading, writing, listening/viewing/speaking, Thai language usage, and literature.','active'
from public.learning_subjects where code='THAI-LANGUAGE'
on conflict(subject_id,code) do update set name=excluded.name,description=excluded.description,status='active',updated_at=now();
insert into public.learning_topics(skill_id,code,name,description,sequence_no,status)
select sk.id,v.code,v.name,v.description,v.seq,'active'
from public.learning_skills sk join public.learning_subjects s on s.id=sk.subject_id and s.code='THAI-LANGUAGE'
cross join (values
 ('TH1.1','การอ่าน','ใช้กระบวนการอ่านสร้างความรู้และความคิด เพื่อนำไปใช้ตัดสินใจ แก้ปัญหาในการดำเนินชีวิตและมีนิสัยรักการอ่าน',1),
 ('TH2.1','การเขียน','ใช้กระบวนการเขียนเขียนสื่อสาร เขียนเรียงความ ย่อความ และเขียนเรื่องราวในรูปแบบต่าง ๆ เขียนรายงานข้อมูลสารสนเทศและรายงานการศึกษาค้นคว้าอย่างมีประสิทธิภาพ',2),
 ('TH3.1','การฟัง การดู และการพูด','สามารถเลือกฟังและดูอย่างมีวิจารณญาณ และพูดแสดงความคิดเห็น ความคิด และความรู้สึกในโอกาสต่างๆ อย่างมีวิจารณญาณและสร้างสรรค์',3),
 ('TH4.1','หลักการใช้ภาษาไทย','เข้าใจธรรมชาติของภาษาและหลักภาษาไทย การเปลี่ยนแปลงของภาษาและพลังของภาษา ภูมิปัญญาทางภาษา และรักษาภาษาไทยไว้เป็นสมบัติของชาติ',4),
 ('TH5.1','วรรณคดีและวรรณกรรม','เข้าใจและแสดงความคิดเห็น วิจารณ์วรรณคดีและวรรณกรรมไทยอย่างเห็นคุณค่า และนำมาประยุกต์ใช้ในชีวิตจริง',5)
) as v(code,name,description,seq)
where sk.code='THAI-LANGUAGE'
on conflict(skill_id,code) do update set name=excluded.name,description=excluded.description,sequence_no=excluded.sequence_no,status='active',updated_at=now();
