insert into public.learning_objectives(topic_id,code,name,description,sequence_no,status)
select t.id,src.objective_code,src.objective_name,src.description,src.sequence_no,'active'
from src join public.learning_skills sk on sk.code='THAI-LANGUAGE'
join public.learning_topics t on t.skill_id=sk.id and t.code=src.standard_code
on conflict(topic_id,code) do update set name=excluded.name,description=excluded.description,sequence_no=excluded.sequence_no,status='active',updated_at=now();
