insert into public.learning_objective_alignments(objective_id,curriculum_id,grade_level_id,sequence_no,required,notes)
select o.id,c.id,g.id,src.indicator_no,true,'Official annual grade-level indicator from OBEC Basic Education Core Curriculum B.E. 2551 (2008), Thai Language standard '||src.standard_code||'.'
from src join public.learning_skills sk on sk.code='THAI-LANGUAGE'
join public.learning_topics t on t.skill_id=sk.id and t.code=src.standard_code
join public.learning_objectives o on o.topic_id=t.id and o.code=src.objective_code
join public.learning_curricula c on c.code='TH-BASIC-CORE-2008-2017'
join public.learning_grade_levels g on g.curriculum_id=c.id and g.code=src.grade_code
on conflict(objective_id,curriculum_id,grade_level_id) do update set sequence_no=excluded.sequence_no,required=excluded.required,notes=excluded.notes,updated_at=now();
commit;